import random

def play_round():
    secret = random.randint(1, 100)
    guesses = 0

    while guesses < 10:
        guess = int(input('Enter guess: '))
        guesses += 1

        if guess == secret:
            print('Win! It took ' + str(guesses) + ' guesses.')
            break
        elif guess < secret:
            print('Low')
        else:
            print('High')
    else:
        print('Out of guesses. The number was ' + str(secret) + '.')
        guesses = 10
    return guesses

def show_menu():
    print('1. Play')
    print('2. View High Score')
    print('3. Quit')

def main():
    high_score = None
    try:
        with open('highscore.txt', 'r') as f:
            high_score = int(f.read().strip())
    except FileNotFoundError:
        high_score = 1000

    while True:
        show_menu()
        choice = input('Select an option: ')

        if choice == '1':
            guesses = play_round()
            if high_score is None or guesses < high_score:
                high_score = guesses
                with open('highscore.txt', 'w') as f:
                    f.write(str(high_score))
                print('New high score: ' + str(high_score) + '!')
        elif choice == '2':
            print('High score: ' + str(high_score) + '.')
        elif choice == '3':
            print('Goodbye!')
            break
        else:
            print('Invalid choice.')

if __name__ == '__main__':
    main()
